function avito_privacy_slug(): string
{
    return 'privacy-policy';
}

function avito_privacy_url(): string
{
    $page = get_page_by_path(avito_privacy_slug());

    return $page ? get_permalink($page) : home_url('/' . avito_privacy_slug() . '/');
}

function avito_agreement(string $text): string
{
    $html = esc_html($text);
    $url = esc_url(avito_privacy_url());

    return preg_replace('/\[\[(.+?)\]\]/u', '<a class="cta__agreement-link" href="' . $url . '">$1</a>', $html);
}

function avito_link_markers(string $text, string $url, string $class = ''): string
{
    $html = esc_html($text);
    $cls = $class !== '' ? ' class="' . esc_attr($class) . '"' : '';

    return preg_replace('/\[\[(.+?)\]\]/u', '<a' . $cls . ' href="' . esc_url($url) . '">$1</a>', $html);
}

